// Package embedded is the shared, build-tag-free lifecycle core for
// embedding the `any` HTTP server inside a host process. Both mobile
// binding shims sit on top of it: the gomobile `mobile` package
// (`mobile/android`) and the c-archive shim (`mobile/ios`). Each shim is a thin
// host-idiom adapter; this package owns the real logic so it is exercised
// once by a single host-runnable test suite.
//
// What it owns:
//   - a mutex-guarded, single-server-per-process reservation covering
//     pending startup as well as a bound listener;
//   - a drain (`stopping`) channel so a fast restart waits for either
//     stop mode's teardown before re-booting on the same data dir
//     (otherwise a background->foreground restart could run two engines
//     against one data dir);
//   - the GOMEMLIMIT soft cap via debug.SetMemoryLimit (iOS jetsam AND
//     Android's low-memory killer);
//   - config assembly: config.Defaults() + DataDir + Listen.Addr +
//     Network.Nodeconf + index policy (Embedder="none": FTS only) +
//     headless (WebUI.Enabled=false) +
//     the push node peer (Options.PushPeerId/PushAddrs → cfg.Push);
//   - the run via main's canonical embedder seam, server.RunWith.
//
// The embedded path never reads config.yaml or ANY_* env — the host owns
// every input and passes it explicitly through Options. Env in a mobile
// app process is not a configuration channel.
//
// It installs NO os/signal handlers — the caller owns the lifecycle.
package embedded

import (
	"context"
	"errors"
	"fmt"
	"runtime/debug"
	"strings"
	"sync"

	"github.com/anyproto/any/internal/config"
	"github.com/anyproto/any/internal/server"
	"github.com/anyproto/any/internal/version"
)

// Exported sentinel errors. Code maps them, and every other Start error,
// to the start code both mobile shims return (codes.go).
//
// An empty nodeconfYAML is not an error: it selects the embedded
// production nodeconf, the same default the CLI and desktop sidecar boot
// on. Hosts pass YAML only to override the network.
var (
	// ErrAlreadyRunning: this process already owns a running server or a
	// pending start. The caller must await or Stop that attempt first.
	ErrAlreadyRunning = errors.New("embedded: server already running")
	// ErrBadDataDir: the data directory argument is empty, or could not be
	// resolved / created (bad path, unwritable parent).
	ErrBadDataDir = errors.New("embedded: bad data directory")
	// ErrBadOptions: an Options field the host controls is invalid — an
	// unknown Mode, managed mode without a ControlToken, or a NodeconfYAML
	// that isn't YAML or names no networkId.
	ErrBadOptions = errors.New("embedded: bad options")
)

// BootError wraps a failure after the config validated: engine or
// account boot, listener bind, or a config the runtime rejected. Code
// maps it by its cause, CodeBootFailed when the cause has no code.
type BootError struct{ Err error }

func (e *BootError) Error() string {
	if e.Err == nil {
		return "embedded: server boot failed"
	}
	return "embedded: server boot failed: " + e.Err.Error()
}

func (e *BootError) Unwrap() error { return e.Err }

// gomemlimitBytes is the GOMEMLIMIT soft cap applied at the start of
// Start so Go's GC pacing keeps RSS clear of iOS jetsam and Android's
// low-memory killer.
//
// The cap must sit well above the live heap of a large account, or the
// runtime enters limit-driven collection: a cycle per fraction of a
// megabyte allocated, each marking the whole live heap, at the GC CPU
// limiter's 50% of every core. A 22-space account holds ~250 MB live
// (any-store v2 page buffers alone are ~120 MB), so 256 MiB measured
// 15 GC cycles/s and 4 of 8 cores in mark work for the whole cold sync.
// 2 GiB leaves normal GOGC pacing in charge and still bounds a runaway.
const gomemlimitBytes = 2 << 30 // 2 GiB

// handle is the package-level, mutex-guarded reservation. It is published
// before startup and remains address-less until Ready. Start guards every
// native export against overlap; Stop can also cancel an unpublished start.
var (
	handleMu sync.Mutex
	handle   *serverHandle
	// stopping covers a cancelled running or pending start. Both stop
	// modes publish it before releasing ownership. A cancelled pending
	// start retains any prior drain in its completion chain.
	stopping chan struct{}
)

type serverHandle struct {
	cancel context.CancelFunc // cancels the RunWith ctx
	done   chan struct{}      // closed after prior drain and full attempt completion
	addr   string             // the bound listen address (host:port)
}

// Options are the host-supplied inputs for Start. The embedded path has
// no config file and no env — every knob a host can turn crosses this
// struct explicitly.
type Options struct {
	// DataDir is the server's data root (Context.getFilesDir() on
	// Android, the app container on iOS). Required.
	DataDir string
	// ListenAddr is the loopback listen address; "127.0.0.1:0" lets the
	// OS pick a free port (read it back with Address()).
	ListenAddr string
	// NodeconfYAML is the any-sync network config contents (staging/prod
	// yml). Empty selects the embedded production nodeconf.
	NodeconfYAML string
	// PushPeerId is the push node's peer id. The push node is a
	// direct out-of-band peer, deliberately NOT part of NodeconfYAML —
	// but it pairs with the nodeconf choice (staging vs prod), so the
	// host supplies both from the same place. With PushAddrs and
	// NodeconfYAML also empty, the production push node applies;
	// otherwise empty = push stays off (409 push.disabled).
	PushPeerId string
	// PushAddrs are the push node's dial addresses, comma-separated —
	// the same format ANY_PUSH_ADDRS parses, e.g.
	// "quic://host:port" or "host:port,host2:port2". A host-named push
	// node needs both PushPeerId and PushAddrs (see PushPeerId).
	PushAddrs string
	// GlobalP2PEnabled overrides the internet-wide p2p layer: an iroh
	// UDP endpoint, a permanent relay session, and a dialable ticket
	// published into the records of every space this account holds.
	// nil takes the same default the CLI gets — on when the host
	// supplied no NodeconfYAML, i.e. the production network. A host
	// that does not want the endpoint sets this to false; there is no
	// config file or env on this path, so this struct is the only way
	// to say so. Publishing a ticket is one-way (docs/30-global-p2p.md
	// § Advertising is a one-way door), so a host that is unsure
	// should decide before the first boot, not after.
	GlobalP2PEnabled *bool

	// Mode is the server ownership mode: "" / "standalone" (the account
	// resolves from the wallet on disk) or "managed" (the host states
	// the account over POST /v1/auth on every boot, keys never touch
	// disk, and logout / switch / shutdown are allowed behind
	// ControlToken). Fixed for the server's lifetime.
	Mode string
	// LocalDiscovery is p2p.localDiscovery: whether mDNS announce and
	// browse start with the engine. nil resolves per platform and mode
	// (config.LocalDiscoveryEnabled). An embedded host that owns a
	// Local Network permission flow passes false here rather than over
	// HTTP: a standalone server with an account on disk boots before the
	// listener is up, so a PUT /v1/local-discovery could not precede it.
	LocalDiscovery *bool
	// ControlToken gates the managed control operations (POST/DELETE
	// /v1/auth, POST /v1/shutdown, PUT /v1/local-discovery). Required
	// when Mode is "managed":
	// an in-process host has no stdout handshake to receive a minted
	// one, and without a token any other process on the device could
	// switch the account. Ignored in standalone.
	ControlToken string
}

// validateOptions checks the host-controlled fields that have no
// filesystem side to fail on. Split from assembleConfig so the
// assembly stays infallible.
func validateOptions(opts Options) error {
	mode, err := config.ParseMode(opts.Mode)
	if err != nil {
		return fmt.Errorf("%w: %w", ErrBadOptions, err)
	}
	if mode == config.ModeManaged && strings.TrimSpace(opts.ControlToken) == "" {
		return fmt.Errorf("%w: managed mode requires ControlToken", ErrBadOptions)
	}
	if nc := strings.TrimSpace(opts.NodeconfYAML); nc != "" {
		if _, err := config.NodeconfNetworkId([]byte(nc)); err != nil {
			return fmt.Errorf("%w: %w", ErrBadOptions, err)
		}
	}
	return nil
}

// assembleConfig builds the embedded boot config from validated Options.
// Split from Start so the assembly rules (index policy, headless,
// push-node threading) are unit-testable without booting an engine.
func assembleConfig(opts Options) config.Config {
	cfg := config.Defaults()
	cfg.DataDir = opts.DataDir
	cfg.Listen.Addr = opts.ListenAddr
	// Already validated by Start; "" normalizes to standalone.
	cfg.Mode, _ = config.ParseMode(opts.Mode)
	// Trimmed so a whitespace-only string counts as "not supplied" and
	// falls through to config's embedded production default, rather than
	// reaching any-sync as an unparseable conf.
	cfg.Network.Nodeconf = strings.TrimSpace(opts.NodeconfYAML)
	// FTS-only index policy, not a host parameter: "none" makes the
	// embedder factory return a true-nil, so no vector pipeline runs
	// in-process. Index.Enabled keeps its config.Defaults() value (on).
	cfg.Index.Embedder = "none"
	// Every in-process boot is headless — no /ui debug harness, no
	// advertising log.
	cfg.WebUI.Enabled = false
	// Push node: plain field fill — the config.Push tristate does
	// the enablement on its own (nil Enabled + non-empty PeerId + addrs ⇒
	// Active). Empty inputs leave the defaults for ApplyPushDefaults.
	cfg.Push.PeerId = opts.PushPeerId
	cfg.Push.Addrs = splitAddrs(opts.PushAddrs)
	cfg.P2P.LocalDiscovery = opts.LocalDiscovery
	// Same rule the CLI gets from config.Load: a host that supplied
	// neither a push node nor a network lands on the production pair.
	config.ApplyPushDefaults(&cfg)
	// Global p2p rides the same pairing: a host that supplied no
	// NodeconfYAML gets the layer, and GlobalP2PEnabled is how it says
	// otherwise, since this path reads neither a config file nor ANY_* env.
	config.ApplyGlobalP2PDefaults(&cfg)
	if opts.GlobalP2PEnabled != nil {
		v := *opts.GlobalP2PEnabled
		cfg.P2P.Global.Enabled = &v
	}
	return cfg
}

// splitAddrs splits a comma-separated address list into trimmed,
// non-empty entries — the same semantics config's ANY_PUSH_ADDRS
// parsing applies, kept here so both mobile shims share one
// implementation instead of each parsing host input.
func splitAddrs(v string) []string {
	if v == "" {
		return nil
	}
	parts := strings.Split(v, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}

// Start boots the embedded server with its data under opts.DataDir,
// listening on opts.ListenAddr, joining the network described by
// opts.NodeconfYAML (see Options for the full input contract). It blocks
// until the listener binds — returning the bound address — or boot fails,
// returning one of the package's typed errors (ErrAlreadyRunning,
// ErrBadDataDir, ErrBadOptions or a *BootError); Code maps it.
func Start(opts Options) (string, error) {
	return startEmbeddedWithBinding(opts, nil)
}

// The original lifecycle remains shared by legacy and network-bound starts.
// A non-nil binding requests the independent identity of this exact boot.
func startEmbeddedWithBinding(opts Options, binding *BoundStartResult) (string, error) {
	return startEmbeddedWithRunner(opts, binding, func(ctx context.Context, cfg config.Config, options server.RunOptions) error {
		return server.RunWith(ctx, cfg, options)
	})
}

// The runner seam is private. Production always supplies canonical RunWith;
// controlled tests can hold the pre-Ready and teardown boundaries without a
// package-global runner override or another lifecycle implementation.
type embeddedRunFunc func(context.Context, config.Config, server.RunOptions) error

func startEmbeddedWithRunner(opts Options, binding *BoundStartResult, run embeddedRunFunc) (string, error) {
	debug.SetMemoryLimit(gomemlimitBytes)

	// Reserve ownership before releasing the lock, including while waiting for
	// a previous drain or validating options. A second native export cannot
	// launch another engine in the interval before Ready publishes an address.
	handleMu.Lock()
	if handle != nil {
		handleMu.Unlock()
		return "", ErrAlreadyRunning
	}
	prev := stopping
	ctx, cancel := context.WithCancel(context.Background())
	h := &serverHandle{cancel: cancel, done: make(chan struct{})}
	handle = h
	handleMu.Unlock()

	runStarted := false
	defer func() {
		if !runStarted {
			cancel()
			finishEmbeddedHandle(h)
		}
	}()

	// A cancelled pending start still owns its done barrier until the prior
	// engine is fully drained. Closing it early would let a later restart
	// bypass that engine's teardown through an already-completed barrier.
	if prev != nil {
		<-prev
	}
	if err := ctx.Err(); err != nil {
		return "", &BootError{Err: err}
	}
	if opts.DataDir == "" {
		return "", ErrBadDataDir
	}
	if err := validateOptions(opts); err != nil {
		return "", err
	}
	cfg := assembleConfig(opts)
	if binding != nil {
		networkID, err := pinBoundNetwork(&cfg)
		if err != nil {
			return "", err
		}
		binding.NetworkID = networkID
	}
	if err := ctx.Err(); err != nil {
		return "", &BootError{Err: err}
	}
	if _, err := config.EnsureDataDir(opts.DataDir); err != nil {
		return "", fmt.Errorf("%w: %w", ErrBadDataDir, err)
	}
	if err := ctx.Err(); err != nil {
		return "", &BootError{Err: err}
	}

	ready := make(chan string, 1)
	runErr := make(chan error, 1)
	runStarted = true
	go func() {
		defer func() {
			cancel()
			finishEmbeddedHandle(h)
		}()
		runErr <- run(ctx, cfg, server.RunOptions{
			Ready:        func(addr string) { ready <- addr },
			ControlToken: strings.TrimSpace(opts.ControlToken),
		})
	}()

	select {
	case addr := <-ready:
		handleMu.Lock()
		current := handle == h && ctx.Err() == nil
		if current {
			h.addr = addr
		}
		handleMu.Unlock()
		if !current {
			// Stop may have cancelled this start while Ready was pending.
			// Its late address must never become the current engine handle.
			cancel()
			<-h.done
			err := <-runErr
			if err == nil {
				err = ctx.Err()
			}
			return "", &BootError{Err: err}
		}
		return addr, nil
	case err := <-runErr:
		cancel()
		<-h.done
		if err == nil {
			err = errors.New("server exited without binding")
		}
		return "", &BootError{Err: err}
	case <-ctx.Done():
		<-h.done
		err := <-runErr
		if err == nil {
			err = ctx.Err()
		}
		return "", &BootError{Err: err}
	}
}

// Exactly one path owns this completion: the Start defer before a runner is
// launched, or the runner goroutine after RunWith has returned. It clears only
// this generation, never a later reservation or a later drain barrier.
func finishEmbeddedHandle(h *serverHandle) {
	handleMu.Lock()
	defer handleMu.Unlock()
	if handle == h {
		handle = nil
	}
	if stopping == h.done {
		stopping = nil
	}
	close(h.done)
}

// Stop cancels the current running or pending start. Both stop modes retain its
// drain barrier before clearing the handle, so a restart waits for full native
// teardown. Graceful Stop also waits for an already pending hard-stop drain.
// Non-graceful Stop never waits for validation, startup or engine shutdown.
func Stop(graceful bool) {
	handleMu.Lock()
	h := handle
	if h == nil {
		prev := stopping
		handleMu.Unlock()
		if graceful && prev != nil {
			<-prev
		}
		return
	}
	handle = nil
	stopping = h.done
	handleMu.Unlock()

	h.cancel()
	if graceful {
		<-h.done
	}
}

// StopNow hard-stops the server and returns promptly (well under 1s): it
// cancels the run context to force the listener closed but does NOT wait
// for a clean drain. The iOS beginBackgroundTask expiration handler calls
// this synchronously, so it must not block on shutdown.
func StopNow() { Stop(false) }

// Address returns the actually-bound listen address (host:port). Differs
// from the listenAddr passed to Start when ":0" was used and the OS
// picked a port. Empty when the server is not running.
func Address() string {
	handleMu.Lock()
	defer handleMu.Unlock()
	if handle == nil {
		return ""
	}
	return handle.addr
}

// Version returns the build-stamped version string ("any <version>
// (commit <sha>, built <ts>)").
func Version() string { return version.String() }

package embedded

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"runtime/debug"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/anyproto/any/internal/config"
	"github.com/anyproto/any/internal/server"
)

// These controlled runners exercise the production lifecycle state machine.
// Only TestConcurrentLegacyAndBoundStartsShareOneManagedRuntime below uses
// real exported Start/StartBound and canonical server.RunWith.
type lifecycleOutcome struct {
	address string
	binding BoundStartResult
	err     error
}

type lifecycleGate struct {
	done chan struct{}
	once sync.Once
}

func newLifecycleGate(t *testing.T) *lifecycleGate {
	t.Helper()
	g := &lifecycleGate{done: make(chan struct{})}
	t.Cleanup(g.release)
	return g
}

func (g *lifecycleGate) release() { g.once.Do(func() { close(g.done) }) }

func setupLifecycle(t *testing.T) {
	t.Helper()
	resetState(t)
	previousLimit := debug.SetMemoryLimit(-1)
	// Later cleanup gates run first, so a failed assertion cannot leave a
	// controlled runner blocked while the final graceful stop is draining.
	t.Cleanup(func() {
		Stop(true)
		debug.SetMemoryLimit(previousLimit)
		current, _, drain := lifecycleState()
		if current != nil || drain != nil {
			t.Error("lifecycle cleanup retained ownership or a drain")
		}
	})
}

func lifecycleOptions(t *testing.T, name string) Options {
	t.Helper()
	return lifecycleOptionsAt(t.TempDir(), name)
}

func lifecycleOptionsAt(root, name string) Options {
	disabled := false
	return Options{
		DataDir: filepath.Join(root, name), ListenAddr: "127.0.0.1:0",
		NodeconfYAML: "networkId: pinkha-lifecycle-fence\nnodes: []\n",
		Mode:         "managed", ControlToken: "lifecycle-test-capability",
		LocalDiscovery: &disabled, GlobalP2PEnabled: &disabled,
	}
}

func lifecycleState() (*serverHandle, string, chan struct{}) {
	handleMu.Lock()
	defer handleMu.Unlock()
	address := ""
	if handle != nil {
		address = handle.addr
	}
	return handle, address, stopping
}

func callLifecycleCore(opts Options, bound bool, run embeddedRunFunc) lifecycleOutcome {
	var outcome lifecycleOutcome
	var requested *BoundStartResult
	if bound {
		requested = &outcome.binding
	}
	outcome.address, outcome.err = startEmbeddedWithRunner(opts, requested, run)
	return outcome
}

func startLifecycleCore(opts Options, bound bool, run embeddedRunFunc) <-chan lifecycleOutcome {
	result := make(chan lifecycleOutcome, 1)
	go func() { result <- callLifecycleCore(opts, bound, run) }()
	return result
}

func awaitLifecycleSignal(t *testing.T, signal <-chan struct{}, description string) {
	t.Helper()
	select {
	case <-signal:
	case <-time.After(5 * time.Second):
		t.Fatal("timed out: " + description)
	}
}

func awaitLifecycleOutcome(t *testing.T, result <-chan lifecycleOutcome) lifecycleOutcome {
	t.Helper()
	select {
	case value := <-result:
		return value
	case <-time.After(20 * time.Second):
		t.Fatal("lifecycle caller did not return")
		return lifecycleOutcome{}
	}
}

func awaitLifecycleReservation(t *testing.T, previous *serverHandle) *serverHandle {
	t.Helper()
	deadline := time.NewTimer(5 * time.Second)
	defer deadline.Stop()
	tick := time.NewTicker(time.Millisecond)
	defer tick.Stop()
	for {
		current, address, _ := lifecycleState()
		if current != nil && current != previous {
			if address != "" {
				t.Fatal("pending restart published an address before its predecessor drained")
			}
			return current
		}
		select {
		case <-deadline.C:
			t.Fatal("new start did not reserve its generation")
		case <-tick.C:
		}
	}
}

func requireLifecycleHeld(t *testing.T, returned <-chan struct{}, description string) {
	t.Helper()
	select {
	case <-returned:
		t.Fatal("returned before the controlled drain: " + description)
	case <-time.After(25 * time.Millisecond):
	}
}

func stopLifecycleNow(t *testing.T) {
	t.Helper()
	returned := make(chan struct{})
	go func() { StopNow(); close(returned) }()
	select {
	case <-returned:
	case <-time.After(time.Second):
		t.Fatal("StopNow waited for a controlled startup or drain")
	}
}

func TestLifecycleReservationCoversPendingLegacyAndBoundStarts(t *testing.T) {
	for _, firstBound := range []bool{false, true} {
		name := "legacy-core"
		if firstBound {
			name = "bound-core"
		}
		t.Run(name, func(t *testing.T) {
			setupLifecycle(t)
			ready := newLifecycleGate(t)
			entered := make(chan struct{})
			var calls atomic.Int32
			runner := func(ctx context.Context, _ config.Config, options server.RunOptions) error {
				if calls.Add(1) != 1 {
					return errors.New("an overlapping caller launched a second runner")
				}
				close(entered)
				<-ready.done
				options.Ready("127.0.0.1:41001")
				<-ctx.Done()
				return ctx.Err()
			}
			first := startLifecycleCore(lifecycleOptions(t, "first"), firstBound, runner)
			awaitLifecycleSignal(t, entered, "first runner entered before Ready")
			reserved, address, _ := lifecycleState()
			if reserved == nil || address != "" || Address() != "" {
				t.Fatal("pending startup was not reserved without an address")
			}
			for _, competingBound := range []bool{false, true} {
				opts := lifecycleOptions(t, "refused")
				outcome := awaitLifecycleOutcome(t, startLifecycleCore(opts, competingBound, runner))
				if !errors.Is(outcome.err, ErrAlreadyRunning) || outcome.address != "" {
					t.Fatalf("pending double start: address %q, error %v", outcome.address, outcome.err)
				}
				if _, err := os.Lstat(opts.DataDir); !errors.Is(err, os.ErrNotExist) {
					t.Fatalf("refused start touched its data directory: %v", err)
				}
			}
			if calls.Load() != 1 {
				t.Fatal("the singleton guard admitted another runner")
			}
			ready.release()
			outcome := awaitLifecycleOutcome(t, first)
			if outcome.err != nil || outcome.address != "127.0.0.1:41001" || Address() != outcome.address {
				t.Fatalf("first reservation failed: %#v", outcome)
			}
			Stop(true)
		})
	}
}

func TestLifecycleCancelledPendingStartCannotSkipPreviousDrain(t *testing.T) {
	setupLifecycle(t)
	drain := newLifecycleGate(t)
	cancelled := make(chan struct{})
	first := startLifecycleCore(lifecycleOptions(t, "first"), false,
		func(ctx context.Context, _ config.Config, options server.RunOptions) error {
			options.Ready("127.0.0.1:41011")
			<-ctx.Done()
			close(cancelled)
			<-drain.done
			return ctx.Err()
		})
	if value := awaitLifecycleOutcome(t, first); value.err != nil {
		t.Fatal(value.err)
	}
	firstHandle, _, _ := lifecycleState()
	stopLifecycleNow(t)
	awaitLifecycleSignal(t, cancelled, "first cancellation")
	var secondRuns atomic.Int32
	second := startLifecycleCore(lifecycleOptions(t, "cancelled-pending"), true,
		func(context.Context, config.Config, server.RunOptions) error {
			secondRuns.Add(1)
			return errors.New("cancelled pending start reached its runner")
		})
	secondHandle := awaitLifecycleReservation(t, firstHandle)
	stopLifecycleNow(t)
	thirdEntered := make(chan struct{})
	third := startLifecycleCore(lifecycleOptions(t, "third"), false,
		func(ctx context.Context, _ config.Config, options server.RunOptions) error {
			close(thirdEntered)
			select {
			case <-firstHandle.done:
			default:
				return errors.New("third generation bypassed the original drain")
			}
			select {
			case <-secondHandle.done:
			default:
				return errors.New("third generation bypassed its cancelled predecessor")
			}
			options.Ready("127.0.0.1:41013")
			<-ctx.Done()
			return ctx.Err()
		})
	thirdHandle := awaitLifecycleReservation(t, secondHandle)
	_, _, pendingDrain := lifecycleState()
	if pendingDrain != secondHandle.done || thirdHandle == firstHandle {
		t.Fatal("cancelled-start drain chain lost its generation")
	}
	requireLifecycleHeld(t, secondHandle.done, "cancelled pending start")
	requireLifecycleHeld(t, thirdEntered, "third runner")
	drain.release()
	secondResult := awaitLifecycleOutcome(t, second)
	if !errors.Is(secondResult.err, context.Canceled) || secondResult.address != "" || secondRuns.Load() != 0 {
		t.Fatalf("cancelled predecessor ran or succeeded: %#v, runners %d", secondResult, secondRuns.Load())
	}
	thirdResult := awaitLifecycleOutcome(t, third)
	if thirdResult.err != nil || thirdResult.address != "127.0.0.1:41013" || Address() != thirdResult.address {
		t.Fatalf("safe later generation failed: %#v", thirdResult)
	}
